    "audio.defaultDevice": {};
    "audio.devices": {};
    "audio.inUse": {};
    "audio.volume": {};
    "camera.inUse": {};
    "usb.attached": {};
    "usb.detached": {};
    "hid.attached": {};
    "hid.detached": {};
    "bluetooth.devices": {};
    "time.clockSet": {};
    "time.zone": {};
